import{_ as t,o as i,c as r,a2 as a}from"./chunks/framework.Cm6XCzck.js";const h=JSON.parse('{"title":"10. Conformance and Testability","description":"","frontmatter":{},"headers":[],"relativePath":"en/publications/tmpa-core-specification-s1.0/part-05.md","filePath":"en/publications/tmpa-core-specification-s1.0/part-05.md","lastUpdated":1786439037000}'),n={name:"en/publications/tmpa-core-specification-s1.0/part-05.md"};function o(s,e,d,c,l,p){return i(),r("div",null,[...e[0]||(e[0]=[a('<p>A participant SHALL NOT perform a protected action outside the active scope of its role.</p><p>A deployment claiming separation of duties SHALL define and enforce incompatible role combinations for the same governed result.</p><p>Role assignment, revocation, delegation, and separation-of-duty exceptions SHOULD themselves be represented as governance objects.</p><p>Role and authority evaluation SHALL follow the order in Section 6.2. Proven denial or an out-of-scope action SHALL be <code>invalid</code>; missing or ambiguous assignment evidence SHALL be <code>undetermined</code>.</p><h2 id="_9-5-stream-requirements" tabindex="-1">9.5 Stream Requirements <a class="header-anchor" href="#_9-5-stream-requirements" aria-label="Permalink to &quot;9.5 Stream Requirements&quot;">​</a></h2><p>Every stream SHALL have a stable stream identifier.</p><p>Every published object SHALL belong to exactly one writer stream. A conforming profile SHALL preserve the local publication order of that writer and SHALL NOT require multiple writers to co-author one mutable object.</p><p>Independent streams MAY progress asynchronously and SHALL NOT be required to advance in lockstep. The absence of a new object in one stream SHALL NOT prevent unrelated streams from progressing when the profile defines no dependency.</p><p>Sequence numbers SHALL be positive integers and SHALL be unique within a stream.</p><p>A reader SHALL report a duplicate sequence number as a stream-integrity error and SHALL preserve every conflicting candidate for inspection.</p><p>A reader SHALL report a sequence gap and SHALL NOT invent the missing object, infer its content, or use timestamps to replace the missing sequence position.</p><p>Wall-clock timestamps SHALL NOT be the sole authoritative ordering mechanism.</p><p>A reader SHALL NOT infer an authoritative order between objects in different streams unless the applicable profile defines a cross-stream causal, lifecycle, or dependency relation. Objects without such a relation SHALL remain concurrent or incomparable in the reconstructed governance graph.</p><h2 id="_9-6-lifecycle-requirements" tabindex="-1">9.6 Lifecycle Requirements <a class="header-anchor" href="#_9-6-lifecycle-requirements" aria-label="Permalink to &quot;9.6 Lifecycle Requirements&quot;">​</a></h2><p>Every lifecycle profile SHALL define:</p><ul><li>states;</li><li>an initial state;</li><li>terminal states;</li><li>actions;</li><li>legal transitions;</li><li>authorized roles;</li><li>preconditions;</li><li>required evidence.</li></ul><p>Every lifecycle profile SHALL have a stable identifier, version, and byte digest. A reader SHALL validate transitions in the order defined by Section 6.2, reconstruct state as defined by Section 6.3, and apply only transitions judged <code>valid</code>. If the unique current state cannot be reconstructed, the candidate transition SHALL be <code>undetermined</code> and SHALL NOT alter authoritative state.</p><p>An illegal or unauthorized transition SHALL NOT alter the authoritative lifecycle state.</p><p>The attempted transition SHALL remain observable through a rejection, issue, alert, or equivalent profile-defined record unless the attempt cannot be captured by the deployment&#39;s stated threat model.</p><p>A terminal-state or archival operation SHALL preserve the objects and transition evidence required to reconstruct how that state was reached.</p><h2 id="_9-7-reference-requirements" tabindex="-1">9.7 Reference Requirements <a class="header-anchor" href="#_9-7-reference-requirements" aria-label="Permalink to &quot;9.7 Reference Requirements&quot;">​</a></h2><p>Every reference SHALL identify a relation type and target object identifier.</p><p>A profile SHALL define which reference types create ordering dependencies, which are non-ordering links, and which relation classes must be acyclic.</p><p>The relation registry SHALL have a stable identifier, version, and byte digest, and the reader result SHALL identify the exact revision used.</p><p>A missing target SHALL be reported. The referencing object MAY remain in a partial view, but the missing dependency SHALL NOT be treated as satisfied.</p><p>A reader SHALL quarantine the affected subgraph of a prohibited cycle rather than silently deleting an edge or selecting an arbitrary order. Unaffected valid objects SHOULD remain reconstructable.</p><h2 id="_9-8-integrity-requirements" tabindex="-1">9.8 Integrity Requirements <a class="header-anchor" href="#_9-8-integrity-requirements" aria-label="Permalink to &quot;9.8 Integrity Requirements&quot;">​</a></h2><p>The canonicalization and digest algorithms SHALL be declared by a versioned integrity profile.</p><p>The integrity profile SHALL define the exact fields or bytes covered by the digest and, when applicable, the signature. It SHALL define how <code>digest</code>, <code>signature_algorithm</code>, <code>key_id</code>, and <code>signature</code> are excluded or normalized to avoid self-reference.</p><p>The profile SHALL also define character encoding, Unicode normalization, line endings, field ordering, whitespace and escaping, number and timestamp representation, absent-versus-null handling, textual-body treatment, attachment hashing, extension-field treatment, and the schema and profile versions bound to the canonical form. Unknown extension fields SHALL either be included deterministically in the covered representation or rejected; they SHALL NOT influence authoritative semantics while being silently excluded from integrity protection.</p><p>A reader SHALL recompute and verify the digest before accepting an object as intact. A digest mismatch SHALL be reported, and the object SHALL NOT enter the intact authoritative object set, although the source SHALL remain available as evidence of the failure.</p><p>When signature metadata is present, <code>signature_algorithm</code>, <code>key_id</code>, and <code>signature</code> SHALL be supplied as one complete group. The reader SHALL validate the signature, key status, and identity binding before claiming authenticated integrity.</p><p>An absent signature is permitted under TMPA Core. An unverifiable signature SHALL NOT be treated as valid evidence of authenticated integrity.</p><p>A deployment SHALL NOT present schema validity, digest validity, signature validity, role authorization, or lifecycle legality as proof that an object&#39;s factual claims are true. Semantic assurance requires a declared evidence and verification profile outside TMPA Core.</p><p>A deployment SHALL NOT claim resistance to an attacker who can alter both content and unanchored integrity metadata solely because a co-located digest is present. Such a claim requires authenticated integrity, externally anchored digests, trusted storage, or an equivalent declared control.</p><h2 id="_9-9-aggregation-and-reader-reconstruction-requirements" tabindex="-1">9.9 Aggregation and Reader-Reconstruction Requirements <a class="header-anchor" href="#_9-9-aggregation-and-reader-reconstruction-requirements" aria-label="Permalink to &quot;9.9 Aggregation and Reader-Reconstruction Requirements&quot;">​</a></h2><p>A conforming source aggregator SHALL preserve source identity and content, discover candidates without using enumeration order as governance order, and produce a deterministic canonical candidate set for the reader. It SHALL NOT silently resolve conflicts, invent missing objects, or convert a transport or filesystem arrival order into an authoritative process sequence.</p><p>For the same canonical candidate set and fixed rule profile, a conforming governance reader SHALL:</p><ul><li>produce the same canonical reconstructed partial-order graph or view and issue set for every input permutation;</li><li>preserve within-stream order, profile-defined cross-stream relations, and concurrency among incomparable objects;</li><li>preserve source objects unchanged;</li><li>preserve valid conflicting objects until an authorized resolution exists;</li><li>exclude schema-invalid and digest-invalid objects from the authoritative object set while retaining their diagnostic evidence;</li><li>report duplicate identifiers, sequence gaps, duplicate sequences, illegal transitions, unauthorized actions, missing references, prohibited cycles, and integrity failures;</li><li>emit one semantic judgment—<code>valid</code>, <code>invalid</code>, or <code>undetermined</code>—for each governed conclusion and preserve the reason for that judgment;</li><li>distinguish authoritative, partial, disputed, quarantined, and unauthenticated states where those distinctions apply;</li><li>apply a deterministic order to conformance issues and serialized view elements.</li></ul><p>The fixed rule profile SHALL include every input listed in Section 8.1. The reader SHALL emit the envelope defined by Section 8.2, use the Core issue codes and identifiers defined there, and apply the three-valued composition rules in Section 7.3. Canonical output ordering SHALL follow Section 8.3.</p><p>A deterministic topological serialization or display tie-breaker SHALL NOT be interpreted as a governance decision, truth priority, or additional cross-stream order.</p><p>A reader SHALL NOT use input arrival order, filesystem enumeration order, or wall-clock timestamp order to resolve a governance conflict.</p><p>An <code>undetermined</code> dependency SHALL propagate as <code>undetermined</code> to a dependent conclusion until an authorized resolution object satisfies the applicable profile. View classifications explain why the judgment was reached; they SHALL NOT replace or expand the three semantic values.</p><h2 id="_9-10-recovery-requirements" tabindex="-1">9.10 Recovery Requirements <a class="header-anchor" href="#_9-10-recovery-requirements" aria-label="Permalink to &quot;9.10 Recovery Requirements&quot;">​</a></h2><p>A replacement participant SHALL be able to determine, from persistent governance objects and the applicable profile:</p><ul><li>the current authoritative or explicitly partial lifecycle state;</li><li>the responsible role;</li><li>unresolved requirements;</li><li>referenced results, reviews, approvals, and rejections;</li><li>integrity, authority, ordering, reference, and validation issues.</li></ul><p>Recovery SHALL NOT require access to the previous participant&#39;s hidden chain of thought.</p><p>Execution-specific context not represented in governance objects MAY be unavailable; such absence SHALL be reported rather than guessed.</p><h2 id="_9-11-governance-closure-claims-and-human-control-requirements" tabindex="-1">9.11 Governance Closure, Claims, and Human-Control Requirements <a class="header-anchor" href="#_9-11-governance-closure-claims-and-human-control-requirements" aria-label="Permalink to &quot;9.11 Governance Closure, Claims, and Human-Control Requirements&quot;">​</a></h2><p>A work-oriented profile SHALL define the relation semantics for reports, issues, rejection, cancellation, follow-up work, review, acceptance, parent-child derivation, human approval, and archive authorization.</p><p>Lifecycle state and business acceptance SHALL be reconstructed separately. A terminal state, <code>done</code> label, physical archive, or executor completion claim SHALL NOT establish business completion by itself. When valid acceptance evidence is missing, the reader SHALL emit <code>ACCEPTANCE_UNDETERMINED</code>.</p><p>A governance-decision object SHALL remain orthogonal to a lifecycle review stage. An execution report SHALL NOT act as its own independent review, and a governance review SHALL NOT replace a required reciprocal response.</p><p>Every completion, failure, recovery, or acceptance claim SHALL identify a stable claim identifier, predicate, subject, and evidence-object identifier set. Missing required evidence SHALL emit <code>CLAIM_EVIDENCE_MISSING</code>, and the affected conclusion SHALL be <code>undetermined</code>.</p><p>Every accepted work object SHALL eventually have a report, issue, rejection, cancellation, or follow-up-work response. When the profile requires closure and the reader finds none, it SHALL emit <code>RECIPROCITY_MISSING</code> and SHALL NOT interpret silence as success.</p><p>Child work SHALL identify its parent explicitly. When a parent has an unfinished child, an unhandled blocked child, or a child without a reciprocal result, parent completion or acceptance SHALL emit <code>CHILD_WORK_OPEN</code> and remain <code>undetermined</code>.</p><p>A risk object requiring human approval SHALL remain <code>undetermined</code> / <code>pending_human</code> until the reader verifies a separate human-approval object whose type and relation are permitted by the risk policy, whose creator has an active assignment to a permitted approval role, and whose creator differs from the risk-object creator when the profile requires an independent actor. Agent self-approval, role labels without assignment evidence, missing approval, wrong object type, or unauthorized approval SHALL NOT satisfy the requirement and SHALL emit <code>HUMAN_APPROVAL_REQUIRED</code> or the applicable authority issue.</p><p>A profile SHALL publish failure-type and recovery-action registries. Failure and recovery objects SHALL reference the affected work; a recovery object SHALL also reference the triggering failure. A failure SHALL NOT be hidden or overwritten by a success response.</p><p>When current-state observations conflict with transition-history evidence, the reader SHALL emit <code>STATE_EVIDENCE_CONFLICT</code>, preserve both sources, and prevent the conflicting state from becoming the sole authoritative conclusion.</p><p>Inspection and governance-alert objects MAY emit findings and suggested plans, but they SHALL NOT be interpreted as an applied repair, lifecycle transition, or business decision without separate execution evidence.</p><hr><h1 id="_10-conformance-and-testability" tabindex="-1">10. Conformance and Testability <a class="header-anchor" href="#_10-conformance-and-testability" aria-label="Permalink to &quot;10. Conformance and Testability&quot;">​</a></h1><p>Sections 9 and 10 preserve the clause identifiers used by the combined TMPA Draft V1.0 source. This stability allows conformance reports and fixtures to cite the same normative basis across the architecture paper, Core specification, and implementation reports.</p><h2 id="_10-1-conformance-levels" tabindex="-1">10.1 Conformance Levels <a class="header-anchor" href="#_10-1-conformance-levels" aria-label="Permalink to &quot;10.1 Conformance Levels&quot;">​</a></h2><p>TMPA defines three conformance levels:</p><ol><li><strong>TMPA Core Conformance:</strong> implements durable textual messages and state objects, primary-carrier rules, single-writer streams, asynchronous multi-stream progression, deterministic aggregation and governance reconstruction, type rules, roles, lifecycle, integrity verification, and recovery requirements.</li><li><strong>FCoP Profile Conformance:</strong> satisfies TMPA Core through a documented projection to the published FCoP protocol, including its naming, lifecycle, atomic-transition, routing, and evidence rules. Passing tests for one FCoP reference-implementation package is implementation evidence only; it is neither installation of the protocol nor sufficient by itself for this conformance level.</li><li><strong>Authenticated Governance Conformance:</strong> satisfies TMPA Core and validates creator identity through a trusted signature, key, and authorization profile.</li></ol><p>None of these levels certifies the semantic truth of a participant&#39;s claim. Authenticated Governance Conformance can establish which verified principal published an authorized object; claim correctness still depends on the applicable evidence, review, tool-attestation, or domain-verification profile.</p><p>Conformance is a claim about a specified implementation version, profile version, fixture corpus, and result set. Product identity, repository ownership, package publication, or demonstration availability does not itself establish conformance.</p><h2 id="_10-2-required-conformance-tests" tabindex="-1">10.2 Required Conformance Tests <a class="header-anchor" href="#_10-2-required-conformance-tests" aria-label="Permalink to &quot;10.2 Required Conformance Tests&quot;">​</a></h2><p>A TMPA Core conformance suite SHALL include C01–C14. Each result SHALL identify its normative basis and preserve the actual output needed to reproduce the verdict.</p><table tabindex="0"><thead><tr><th>ID</th><th>Test</th><th>Normative basis</th><th>Pass criterion</th></tr></thead><tbody><tr><td>C01</td><td>Schema validation</td><td>4.1, 9.2, 9.3, 9.11</td><td>an object with missing required fields, wrong Core type/version, prohibited fields, malformed transitions, incomplete signatures, malformed claims, invalid risk enums, or invalid asserted <code>date-time</code> is excluded and produces <code>SCHEMA_INVALID</code> deterministically</td></tr><tr><td>C02</td><td>Primary carrier, work derivation, and single-writer immutability</td><td>9.2, 9.11</td><td>one stable task carrier remains identifiable; parent-child work round-trips and is not replaced by a thread; another writer cannot replace or co-edit a published object; correction/supersession uses new attributable evidence</td></tr><tr><td>C03</td><td>Duplicate object identity and source provenance</td><td>9.2, 9.9</td><td>same-ID candidates with different canonical content are retained and quarantined with a deterministic critical conflict; byte-identical observations project one node while retaining every contributing source ID</td></tr><tr><td>C04</td><td>Serial-stream continuity and asynchronous progress</td><td>9.5, 9.9</td><td>each writer preserves its local sequence; duplicate numbers and gaps are reported; unrelated streams can advance independently; no missing object is invented and arrival order does not change the final result for the same set</td></tr><tr><td>C05</td><td>Role authority</td><td>6.2, 9.4, 9.9</td><td>an action outside validated role scope produces <code>AUTHORITY_DENIED</code> and <code>invalid</code>; missing or ambiguous assignment evidence produces <code>AUTHORITY_UNDETERMINED</code> and <code>undetermined</code>; neither action is applied</td></tr><tr><td>C06</td><td>Lifecycle legality, state evidence, and business-acceptance separation</td><td>6.2–6.4, 9.6, 9.9, 9.11</td><td>an undefined transition produces <code>ILLEGAL_TRANSITION</code>; ambiguous state or missing prerequisites produce <code>LIFECYCLE_UNDETERMINED</code>; an observation contradicting reconstructed state produces <code>STATE_EVIDENCE_CONFLICT</code>; completion without independent acceptance produces <code>ACCEPTANCE_UNDETERMINED</code>; none fabricates business completion</td></tr><tr><td>C07</td><td>Separation of duties and human control</td><td>9.3, 9.4, 9.11</td><td>the same identity cannot execute and independently review the same result; self-approval, unassigned role labels, and wrong approval-object types remain pending; only a separate permitted object from an assigned, profile-authorized and, when required, independent approver satisfies the gate</td></tr><tr><td>C08</td><td>Integrity tampering</td><td>9.8, 9.9</td><td>changing covered content while preserving the original integrity metadata causes digest verification to fail; the object is retained as failure evidence but excluded from the intact authoritative set</td></tr><tr><td>C09</td><td>Missing reference and claim evidence</td><td>9.7, 9.9, 9.11</td><td>an unresolved target produces <code>MISSING_REFERENCE</code>; missing evidence for a completion claim produces <code>CLAIM_EVIDENCE_MISSING</code>; neither dependency nor claim is treated as satisfied</td></tr><tr><td>C10</td><td>Prohibited cycle</td><td>9.7, 9.9</td><td>the affected prohibited-cycle subgraph is quarantined and reported while unaffected valid objects remain reconstructable</td></tr><tr><td>C11</td><td>Aggregation and reconstruction determinism</td><td>8, 9.9</td><td>every tested enumeration, delayed-delivery permutation, and aggregation order of the same source set and complete fixed input bundle produces a byte-equivalent canonical result envelope, graph, and issue set; Unicode code-point ordering is locale-independent and unrelated cross-stream objects remain incomparable</td></tr></tbody></table>',70)])])}const m=t(n,[["render",o]]);export{h as __pageData,m as default};
